MATCH (c:Company)-[:hasCEO]->(p:Person {name: "Neal Harmon"})
WHERE EXISTS { MATCH (c)-[:subsidiaryOf]->(:Company {name: "VidAngel"}) }
RETURN c.name, c.launch_year

MATCH (c:Company {name: "BBY Ltd"})-[:hasBoardMember]->(p:Person)
WHERE (c)-[:hasBoardMember]->(p) AND NOT EXISTS {
  MATCH (c)-[r:hasBoardMember]->(p)
  WHERE r.end_year IS NOT NULL
}
RETURN DISTINCT p.name

MATCH (c:Company)-[:basedIn]->(co:Country {name: "El Salvador"})
WHERE EXISTS { MATCH (c)-[:subsidiaryOf]->(:Company {name: "Fremantle"}) }
RETURN c.name, c.launch_year
